import heapq

def minimum_time_to_reach_destination(n, edges, s, t):
    from collections import defaultdict
    g = defaultdict(list)
    for u, v, w in edges:
        g[u].append((v, w))
    INF = 1 << 60
    dist = [INF] * n
    dist[s] = 0
    heap = [(0, s)]
    while heap:
        cost, u = heapq.heappop(heap)
        if u == t:
            return cost
        if cost > dist[u]:
            continue
        for v, w in g[u]:
            if dist[v] > cost + w:
                dist[v] = cost + w
                heapq.heappush(heap, (dist[v], v))
    return -1
